package com.nvv.mediadata.view.coreimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Rowimport androidx.compose.foundation.layout.Spacerimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.layout.widthimport androidx.compose.material3.Iconimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.vector.ImageVectorimport androidx.compose.ui.text.style.TextOverflowimport androidx.compose.ui.unit.dp@Composablefun InforItem(	onClick: () -> Unit,	prefixTitle: String,	iconId: ImageVector? = null,	suffix: @Composable (() -> Unit)? = null) {	Box(modifier = Modifier.clickable { onClick() }) {		Row(			modifier = Modifier				.fillMaxWidth()				.padding(16.dp),			verticalAlignment = Alignment.CenterVertically		) {			// Icon (if provided)			iconId?.let { icon ->				Icon(					imageVector = icon,					contentDescription = null,					modifier = Modifier.size(24.dp),					tint = Color.White				)				Spacer(modifier = Modifier.width(12.dp))			}			// Title text			Text(				text = prefixTitle,				modifier = Modifier.weight(1f),				overflow = TextOverflow.Ellipsis,				color = Color.White,				style = baseStyle			)			// Suffix (if provided)			if (suffix != null) {				Spacer(modifier = Modifier.width(8.dp))				suffix()			}		}	}}